#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
One-Click Repository Integrator & GitHub Publisher for https://github.com/yoyo-ui/direct-stream-ps5 (v3.0.0)

This script integrates all v3.0 features DIRECTLY into the existing codebase:
  1. Links `ps5_direct_stream_pc.py` with the existing `resolver.py`, `transfer_core.py`, and `zip_streamer.py`.
  2. Injects the v3.0 Smart Format Detector, Multi-Console Broadcast, General FTP, and GitHub Auto-Updater
     directly into the existing Android app (`MainActivity.kt`, `DestinationRouter.kt`, `AndroidManifest.xml`).
  3. Installs `.github/workflows/build_apk_and_exe.yml` so GitHub Actions automatically compiles both
     the standalone Windows `DirectStreamPS5_PC.exe` and `DirectStreamPS5_Android.apk`.
"""

import argparse
import pathlib
import subprocess
import sys

GITHUB_WORKFLOW_RELEASE_YML = 'name: Build Standalone Windows EXE & Android APK + Publish Release\n\non:\n  push:\n    branches:\n      - main\n    tags:\n      - \'v*\'\n  workflow_dispatch:\n    inputs:\n      release_tag:\n        description: \'Release version tag to publish (e.g. v3.0.0)\'\n        required: false\n        default: \'v3.0.0\'\n\npermissions:\n  contents: write\n\njobs:\n  # ==========================================================================\n  # JOB 1: Build Standalone Windows .EXE (Bundles legacy engine + v3 updates)\n  # ==========================================================================\n  build-windows-exe:\n    name: Build Standalone PC (.exe) on Windows\n    runs-on: windows-latest\n    steps:\n      - name: Checkout repository\n        uses: actions/checkout@v4\n\n      - name: Set up Python 3.11\n        uses: actions/setup-python@v5\n        with:\n          python-version: \'3.11\'\n\n      - name: Apply v3.0 Integration if apply_repo_updates.py is present\n        run: |\n          if (Test-Path "apply_repo_updates.py") {\n            python apply_repo_updates.py\n          }\n\n      - name: Install PyInstaller\n        run: |\n          python -m pip install --upgrade pip\n          pip install pyinstaller\n\n      - name: Build Standalone GUI & Console .EXE (Bundled with Legacy Engine)\n        run: |\n          pyinstaller --noconfirm --clean --onefile --windowed --name "DirectStreamPS5_PC" `\n            --hidden-import=resolver --hidden-import=transfer_core --hidden-import=zip_streamer --hidden-import=ps5_streamer `\n            ps5_direct_stream_pc.py\n          pyinstaller --noconfirm --clean --onefile --console --name "DirectStreamPS5_PC_CLI" `\n            --hidden-import=resolver --hidden-import=transfer_core --hidden-import=zip_streamer --hidden-import=ps5_streamer `\n            ps5_direct_stream_pc.py\n\n      - name: Package Portable Windows ZIP\n        shell: pwsh\n        run: |\n          Compress-Archive -Path dist/DirectStreamPS5_PC.exe, dist/DirectStreamPS5_PC_CLI.exe, ps5_direct_stream_pc.py -DestinationPath dist/DirectStreamPS5_PC_Windows_Portable.zip -Force\n\n      - name: Upload Windows .EXE Artifacts\n        uses: actions/upload-artifact@v4\n        with:\n          name: DirectStreamPS5-Windows-EXE\n          path: |\n            dist/DirectStreamPS5_PC.exe\n            dist/DirectStreamPS5_PC_CLI.exe\n            dist/DirectStreamPS5_PC_Windows_Portable.zip\n\n  # ==========================================================================\n  # JOB 2: Build Native Android .APK (Existing App + v3 Multi-Console/FTP/AutoUpdate Tab)\n  # ==========================================================================\n  build-android-apk:\n    name: Build Android (.apk) on Ubuntu\n    runs-on: ubuntu-latest\n    steps:\n      - name: Checkout repository\n        uses: actions/checkout@v4\n\n      - name: Set up JDK 17\n        uses: actions/setup-java@v4\n        with:\n          distribution: \'temurin\'\n          java-version: \'17\'\n          cache: \'gradle\'\n\n      - name: Apply v3.0 Integration into Android Project\n        run: |\n          if [ -f "apply_repo_updates.py" ]; then\n            python3 apply_repo_updates.py\n          fi\n\n      - name: Run Core Tests & Assemble Android APK\n        working-directory: ./android\n        run: |\n          chmod +x gradlew\n          ./gradlew :core:test :app:assembleDebug --no-daemon\n\n      - name: Prepare Android APK Asset\n        run: |\n          cp android/app/build/outputs/apk/debug/app-debug.apk ./DirectStreamPS5_Android.apk\n\n      - name: Upload Android APK Artifact\n        uses: actions/upload-artifact@v4\n        with:\n          name: DirectStreamPS5-Android-APK\n          path: DirectStreamPS5_Android.apk\n\n  # ==========================================================================\n  # JOB 3: Publish GitHub Release (Powers In-App GitHub Auto-Update)\n  # ==========================================================================\n  publish-release:\n    name: Publish GitHub Release (EXE + APK)\n    needs: [build-windows-exe, build-android-apk]\n    runs-on: ubuntu-latest\n    steps:\n      - name: Download Windows EXE Artifacts\n        uses: actions/download-artifact@v4\n        with:\n          name: DirectStreamPS5-Windows-EXE\n          path: ./release_assets\n\n      - name: Download Android APK Artifact\n        uses: actions/download-artifact@v4\n        with:\n          name: DirectStreamPS5-Android-APK\n          path: ./release_assets\n\n      - name: Determine Release Tag\n        id: tag\n        run: |\n          if [[ "${GITHUB_REF}" == refs/tags/* ]]; then\n            echo "tag_name=${GITHUB_REF#refs/tags/}" >> $GITHUB_OUTPUT\n          elif [[ -n "${{ github.event.inputs.release_tag }}" ]]; then\n            echo "tag_name=${{ github.event.inputs.release_tag }}" >> $GITHUB_OUTPUT\n          else\n            echo "tag_name=v3.0.0" >> $GITHUB_OUTPUT\n          fi\n\n      - name: Create or Update GitHub Release\n        uses: softprops/action-gh-release@v2\n        with:\n          tag_name: ${{ steps.tag.outputs.tag_name }}\n          name: "Direct Stream PS5 ${{ steps.tag.outputs.tag_name }} — Standalone PC (.exe) + Android (.apk)"\n          generate_release_notes: true\n          prerelease: false\n          files: |\n            release_assets/DirectStreamPS5_PC.exe\n            release_assets/DirectStreamPS5_PC_CLI.exe\n            release_assets/DirectStreamPS5_PC_Windows_Portable.zip\n            release_assets/DirectStreamPS5_Android.apk\n'

